# FMCSA video fix installer — run ON RDP
# powershell -ExecutionPolicy Bypass -File C:\fmcsa_sync\INSTALL_VIDEO_FIX.ps1
$ErrorActionPreference = 'Stop'
$Root = 'C:\fmcsa_sync'
if (-not (Test-Path $Root)) { New-Item -ItemType Directory -Path $Root | Out-Null }
Set-Location $Root

function Write-B64File([string]$Path, [string]$B64) {
  [IO.File]::WriteAllBytes($Path, [Convert]::FromBase64String($B64))
  Write-Host "Wrote $Path ($((Get-Item $Path).Length) bytes)"
}

